// Turns spec/swagger.json + scripts/allowlist.ts into src/generated/tools.ts.
//
// Everything a tool needs is already in the spec, put there deliberately by the
// annotation work in nortezh-backend: `operationId` is the tool name, `binding:"required"`
// became `required[]`, `x-mcp-read-only` / `x-mcp-destructive` are the safety hints, and
// `x-error-codes` lists what the route can return. Nothing here is hand-maintained except
// the allowlist, so a route that changes shape in the API shows up as a diff in the
// generated file rather than as a runtime surprise.
//
// The output is COMMITTED so a clone builds without running codegen, and so a reviewer
// sees exactly what the tool surface became.

import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

import { buildInputSchema, refName } from '../src/schema.js'
import type { SwaggerDocument, SwaggerOperation } from '../src/spec-types.js'
import { ALLOWLIST } from './allowlist.js'

const here = dirname(fileURLToPath(import.meta.url))
const root = resolve(here, '..')

const spec = JSON.parse(readFileSync(resolve(root, 'spec/swagger.json'), 'utf8')) as SwaggerDocument
const definitions = spec.definitions ?? {}

const operations = new Map<string, { path: string; operation: SwaggerOperation }>()
for (const [path, methods] of Object.entries(spec.paths ?? {})) {
  for (const operation of Object.values(methods)) {
    if (operation.operationId !== undefined) {
      operations.set(operation.operationId, { path, operation })
    }
  }
}

const missing = ALLOWLIST.filter((id) => !operations.has(id))
if (missing.length > 0) {
  throw new Error(`generate: allowlist names operations that are not in the spec: ${missing.join(', ')}`)
}

const duplicates = ALLOWLIST.filter((id, i) => ALLOWLIST.indexOf(id) !== i)
if (duplicates.length > 0) {
  throw new Error(`generate: allowlist has duplicate entries: ${duplicates.join(', ')}`)
}

/**
 * A tool description: the route's one-line summary, plus the codes it can fail with.
 *
 * Only the summary, never the full `@Description`. Those run to paragraphs — they are
 * written for a human reading the Scalar page — and including them roughly doubles the
 * per-request context cost of the tool list for very little the model acts on.
 *
 * The error codes earn their place: domain errors arrive as HTTP 200 with `ok:false` and
 * the client turns them into tool errors, so naming the codes lets the model react to a
 * specific one instead of retrying blindly.
 */
function describe(operation: SwaggerOperation): string {
  const summary = (operation.summary ?? '').trim()
  const codes = operation['x-error-codes'] ?? []
  if (codes.length === 0) return summary
  return `${summary}\nMay fail with: ${codes.join(', ')}.`
}

const tools = ALLOWLIST.map((id) => {
  const entry = operations.get(id)
  if (entry === undefined) throw new Error(`generate: unreachable — ${id} vanished`)
  const { path, operation } = entry

  const body = (operation.parameters ?? []).find((parameter) => parameter.in === 'body')
  const rootName = body === undefined ? null : refName(body.schema?.$ref)

  return {
    name: id,
    // Route names are prefix-relative; the client joins them onto NORTEZH_API_URL.
    route: path.replace(/^\//, ''),
    description: describe(operation),
    inputSchema: buildInputSchema(rootName, definitions),
    readOnly: operation['x-mcp-read-only'] === true,
    destructive: operation['x-mcp-destructive'] === true,
    errorCodes: operation['x-error-codes'] ?? [],
  }
})

const banner = `// GENERATED by scripts/generate.ts from spec/swagger.json — do not edit by hand.
// Regenerate with \`npm run generate\`; change what is included in scripts/allowlist.ts.
// Source spec: ${spec.info?.title ?? 'unknown'} ${spec.info?.version ?? ''}`.trim()

const output = `${banner}

export interface ToolSpec {
  /** MCP tool name. Equals the spec's operationId, and is effectively permanent. */
  name: string
  /** arpc route relative to the API base URL, e.g. "deployment.create". */
  route: string
  description: string
  inputSchema: Record<string, unknown>
  readOnly: boolean
  destructive: boolean
  errorCodes: string[]
}

export const TOOLS: ToolSpec[] = ${JSON.stringify(tools, null, 2)}
`

const target = resolve(root, 'src/generated/tools.ts')
writeFileSync(target, output)

const readOnly = tools.filter((tool) => tool.readOnly).length
const destructive = tools.filter((tool) => tool.destructive).length
const listPayload = JSON.stringify(
  tools.map((tool) => ({
    name: tool.name,
    description: tool.description,
    inputSchema: tool.inputSchema,
  })),
).length

console.log(
  `generate: ${tools.length} tools -> src/generated/tools.ts ` +
    `(${readOnly} read-only, ${destructive} destructive, ${tools.length - readOnly - destructive} plain writes)`,
)
// Printed every run because it is the number that quietly grows as the allowlist does,
// and it is charged against every request the model makes.
console.log(`generate: tools/list payload ~${Math.round(listPayload / 1024)}kB (~${Math.round(listPayload / 4000)}k tokens)`)
